package com.family.kitchen;
import android.app.*;
import android.os.Bundle;
import android.widget.*;
import org.json.*;
import java.util.*;

public class OfflineActivity extends Activity {
    private JSONArray recipes; private JSONObject current; private int step;
    private LinearLayout body; private BailianSettings api; private String ingredients=""; private boolean busy;
    private int visibleRecipes=12;
    private android.view.View primary;
    @Override public void onCreate(Bundle state){super.onCreate(state);api=new BailianSettings(this,getPreferences(0));try{
        String saved=getPreferences(0).getString("recipes","");
        if(saved.isEmpty()){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();try(java.io.InputStream in=getAssets().open("recipes.json")){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}saved=out.toString("UTF-8");}
        recipes=new JSONArray(saved);ingredients=getPreferences(0).getString("ingredients","");String active=getPreferences(0).getString("current","");if(!active.isEmpty())current=new JSONObject(active);step=getPreferences(0).getInt("step",0);
    }catch(Exception e){recipes=new JSONArray();toast("读取菜谱失败");}if(current==null)home();else cook();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private android.graphics.drawable.GradientDrawable background(int color){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(18));return d;}
    private void screen(String title){getWindow().setStatusBarColor(0xfff5f3eb);getWindow().setNavigationBarColor(0xfff5f3eb);getWindow().getDecorView().setSystemUiVisibility(android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(22),dp(20),dp(22),dp(32));body.setBackgroundColor(0xfff5f3eb);scroll.addView(body);setContentView(scroll);text("FAMILY KITCHEN / 家庭厨房",12);text(title,30);Button settings=new Button(this);settings.setText("设置 · 百炼连接");settings.setTextColor(0xff526b5c);settings.setBackground(background(0xffe7ecdf));settings.setOnClickListener(v->api.show());body.addView(settings);}
    private void text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff243d30);t.setLineSpacing(dp(5),1);t.setPadding(dp(4),dp(12),dp(4),dp(12));if(size>=24)t.setTypeface(null,1);body.addView(t);}
    private void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setAllCaps(false);b.setTextColor(0xff244b39);b.setGravity(android.view.Gravity.CENTER_VERTICAL);b.setPadding(dp(20),dp(14),dp(20),dp(14));b.setMinHeight(dp(58));b.setBackground(background(0xfffffdf8));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);body.addView(b,p);b.setOnClickListener(v->r.run());}
    private TextView label(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(4),1);return t;}
    private void primary(String title,Runnable action){button(title,action);Button b=(Button)body.getChildAt(body.getChildCount()-1);b.setBackground(background(0xff244b39));b.setTextColor(0xffffffff);b.setGravity(android.view.Gravity.CENTER);primary=b;}
    private EditText field(String hint,String value){EditText e=new EditText(this);e.setText(value);e.setHint(hint);e.setTextSize(16);e.setTextColor(0xff243d30);e.setPadding(dp(16),dp(16),dp(16),dp(16));e.setBackground(background(0xffffffff));e.setMinHeight(dp(60));e.setMaxLines(4);body.addView(e);return e;}
    private void recipeCard(JSONObject recipe){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(20),dp(18),dp(20),dp(18));card.setBackground(background(0xfffffdf8));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(12);body.addView(card,p);TextView name=label(recipe.optString("name"),21,0xff243d30);name.setTypeface(null,1);card.addView(name);TextView meta=label(recipe.optInt("minutes")+" 分钟  ·  "+recipe.optInt("servings",2)+" 人份  ·  匹配 "+score(recipe)+" 种食材",13,0xff657665);meta.setPadding(0,dp(8),0,dp(8));card.addView(meta);JSONArray items=recipe.optJSONArray("ingredients");List<String> names=new ArrayList<>();if(items!=null)for(int i=0;i<Math.min(4,items.length());i++)names.add(items.optString(i));card.addView(label(android.text.TextUtils.join("  /  ",names),14,0xff657665));TextView go=label("查看做法   →",15,0xff244b39);go.setPadding(0,dp(14),0,0);card.addView(go);card.setFocusable(true);card.setContentDescription(recipe.optString("name")+"，查看做法");card.setOnClickListener(v->{current=recipe;step=0;save();cook();});}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    private void save(){getPreferences(0).edit().putString("recipes",recipes.toString()).putString("ingredients",ingredients).putString("current",current==null?"":current.toString()).putInt("step",step).apply();}
    private int score(JSONObject r){Set<String> selected=new HashSet<>();for(String name:ingredients.split("[,，、\\s]+"))if(!name.trim().isEmpty())selected.add(name.trim());int n=0;JSONArray a=r.optJSONArray("ingredients");if(a!=null)for(int i=0;i<a.length();i++)if(selected.contains(a.optString(i)))n++;return n;}
    private List<JSONObject> ranked(){List<JSONObject> l=new ArrayList<>();for(int i=0;i<recipes.length();i++)l.add(recipes.optJSONObject(i));l.sort((a,b)->Integer.compare(score(b),score(a)));return l;}
    private void home(){screen("把日子，煮成喜欢的味道。");text("从冰箱里的食材开始，今天也好好吃饭。",15);text("01  /  今天有什么食材",21);EditText input=field("鸡腿、土豆、鸡蛋…",ingredients);
        HorizontalScrollView chips=new HorizontalScrollView(this);chips.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);chips.addView(row);body.addView(chips);for(String name:new String[]{"鸡蛋","土豆","番茄","鸡腿","豆腐","青菜"}){Button chip=new Button(this);chip.setText("＋ "+name);chip.setTextColor(0xff244b39);chip.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffe7ecdf));row.addView(chip);chip.setOnClickListener(v->{String old=input.getText().toString().trim();Set<String> values=new LinkedHashSet<>(Arrays.asList(old.split("[,，、\\s]+")));values.remove("");values.add(name);input.setText(android.text.TextUtils.join("、",values));});}
        button("用这些食材找菜谱  →",()->{ingredients=input.getText().toString().trim();visibleRecipes=12;save();home();});
        primary(busy?"厨房助手正在想菜谱…":"✦  让 AI 帮我搭配一道菜",()->{ingredients=input.getText().toString().trim();save();if(ingredients.isEmpty()){toast("请填写食材");return;}JSONArray refs=new JSONArray();List<JSONObject> l=ranked();for(int i=0;i<Math.min(3,l.size());i++)refs.put(l.get(i));call("使用已有食材："+ingredients+"，参考菜谱："+refs+"，生成2人份家常菜。只返回JSON对象：name字符串，minutes和servings整数，ingredients主要食材、amounts用量、steps步骤均为字符串数组。不输出代码围栏。所有食材充分熟透，鸡肉中心达到74°C。",true);});
        text("02  /  今天的灵感菜单",21);text(recipes.length()+" 道本地菜谱 · 随时离线查看",13);List<JSONObject> list=ranked();for(int i=0;i<Math.min(visibleRecipes,list.size());i++)recipeCard(list.get(i));if(visibleRecipes<list.size())button("再看 12 道菜",()->{visibleRecipes+=12;home();});}
    private void cook(){screen(current.optString("name"));JSONArray a=current.optJSONArray("amounts"),s=current.optJSONArray("steps");if(s==null||s.length()==0){current=null;save();home();return;}text("约 "+current.optInt("minutes")+" 分钟  ·  "+current.optInt("servings",2)+" 人份",14);step=Math.max(0,Math.min(step,s.length()));ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(s.length());progress.setProgress(step);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff244b39));body.addView(progress);text(step==s.length()?"做得真好，开饭吧！":"STEP "+String.format(java.util.Locale.ROOT,"%02d",step+1)+"  /  "+s.length(),18);TextView instruction=label(step==s.length()?"这道菜已完成。下次打开会保留你的进度。":s.optString(step),26,0xff243d30);instruction.setPadding(dp(20),dp(26),dp(20),dp(26));instruction.setBackground(background(0xfffffdf8));body.addView(instruction);
        if(step<s.length())primary(step==s.length()-1?"完成这道菜  ✓":"做好了，下一步  →",()->{step=Math.min(s.length(),step+1);save();cook();});if(step>0)button("←  回到上一步",()->{step--;save();cook();});button("查看备料与用量",()->{StringBuilder content=new StringBuilder();if(a!=null)for(int i=0;i<a.length();i++)content.append("• ").append(a.optString(i)).append("\n\n");new AlertDialog.Builder(this).setTitle("备料清单").setMessage(content.toString()).setPositiveButton("准备好了",null).show();});text("遇到问题，问问厨房助手",20);EditText q=field("比如：没有生抽可以用什么？","");button("向助手提问  ↗",()->{if(!q.getText().toString().trim().isEmpty())call("根据菜谱回答烹饪问题，注意食品安全。菜谱："+current+" 当前步骤索引："+step+" 问题："+q.getText(),false);});button("返回灵感菜单",()->{current=null;save();home();});}
    private void call(String prompt,boolean generate){if(busy){toast("正在处理，请稍候");return;}busy=true;toast("正在调用百炼…");new Thread(()->{try{String answer=api.ask(prompt);runOnUiThread(()->{busy=false;if(isFinishing()||isDestroyed())return;if(!generate){new AlertDialog.Builder(this).setTitle("厨房助手").setMessage(answer).setPositiveButton("关闭",null).show();return;}try{JSONObject r=new JSONObject(answer);validate(r);new AlertDialog.Builder(this).setTitle("确认 AI 菜谱").setMessage(r.toString(2)).setNegativeButton("取消",null).setPositiveButton("保存并做饭",(d,w)->{recipes.put(r);current=r;step=0;save();cook();}).show();}catch(Exception e){toast("菜谱格式不完整，请重试");}});}catch(Exception e){runOnUiThread(()->{busy=false;toast("调用失败，请检查百炼配置、额度与网络");});}},"kitchen-ai").start();}
    static void validate(JSONObject r)throws JSONException{if(r.getString("name").trim().isEmpty()||r.getInt("minutes")<1||r.getInt("servings")<1)throw new JSONException("Invalid recipe");for(String k:new String[]{"ingredients","amounts","steps"}){JSONArray a=r.getJSONArray(k);if(a.length()<1||a.length()>60)throw new JSONException("Invalid array");for(int i=0;i<a.length();i++)if(!(a.get(i) instanceof String)||a.getString(i).trim().isEmpty())throw new JSONException("Invalid text");}}
}
